    Reset(s); g_spawnPointAlive = true; g_newLevel = "BowerstoneJail"; s.MonitorRegionPresence();   // back to a visited region
    ok = ok && !s.SpawnHere && s.AreasSpawnedIn.size() == 1 && !s.MissionFailed;
