                } else if (distance < secondDistance || secondDistance == -1.0f) {
                    second = &guards[i]; secondDistance = distance;
                }
            }
            if (nearest) AddNewHeroAttacker(*nearest);
            if (second) AddNewHeroAttacker(*second);
        }
    }
}
